"""Compile the reviewed offline snapshot; no runtime downloads or dependencies."""

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def render(snapshot: dict) -> str:
    """Keep data separate from execution; the runtime validates all references."""
    return (
        "# Generated by dev/catalog/build.py from dev/catalog/review.json.\n"
        "# Do not edit; source references and per-provider assessments are included.\n"
        "# ruff: noqa: E501\nimport json\n\n"
        "CATALOG = json.loads(\n"
        + "    "
        + repr(json.dumps(snapshot, ensure_ascii=True, separators=(",", ":")))
        + "\n)\n"
    )


def table(snapshot: dict) -> str:
    """Human-readable index; full A-F evidence remains in the single snapshot."""
    lines = [
        "# Device catalog index",
        "",
        "Generated from [the reviewed snapshot](../dev/catalog/review.json). "
        "Use [the guide](device-compatibility.md) or the panel for filters and limits.",
        "",
        "52 canonical definitions; 67 website model/variant rows. "
        "Every row has separate A-F assessments for both providers. "
        "A listed action depends on eligible HA entities and confirmation. "
        "Physical validation: zero. ZHA standard IAS routes are conditional, "
        "not a claim that every signature creates a siren.",
        "",
        "| Canonical vendor / model | Documented variants | Kind "
        "| MQTT action profile | ZHA action profile |",
        "| --- | --- | --- | --- | --- |",
    ]
    for entry in snapshot["entries"]:
        aliases = (
            "; ".join(f"{a['vendor']} {a['model']}" for a in entry["aliases"]) or "—"
        )
        profiles = [
            entry["providers"][p]["profile"] or "No reviewed action"
            for p in ("zigbee2mqtt", "zha")
        ]
        url = entry["providers"]["zigbee2mqtt"]["sources"][0]
        lines.append(
            f"| [{entry['vendor']} {entry['model']}]({url}) | {aliases} "
            f"| {entry['kind']} | {profiles[0]} | {profiles[1]} |"
        )
    return "\n".join(lines) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    snapshot = json.loads(
        (ROOT / "dev/catalog/review.json").read_text(encoding="utf-8")
    )
    # A generated literal avoids filesystem/network access when HA uses the catalog.
    for output, rendered in (
        (ROOT / "custom_components/alarmmesh/catalog_data.py", render(snapshot)),
        (ROOT / "docs/device-catalog.md", table(snapshot)),
    ):
        if args.check:
            if output.read_text(encoding="utf-8") != rendered:
                raise SystemExit("Catalog is stale: run python dev/catalog/build.py")
        else:
            output.write_text(rendered, encoding="utf-8")


if __name__ == "__main__":
    main()
